inline ::flatbuffers::Offset<MDEEvidence> CreateMDEEvidence(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    mdeDetector DETECTOR = mdeDetector_Unspecified,
    int64_t TIME_MS = 0,
    int32_t PAIR_INDEX = -1,
    double STEP_IN_TRACK_M_S = std::numeric_limits<double>::quiet_NaN(),
    double STEP_PLANE_M_S = std::numeric_limits<double>::quiet_NaN(),
    double THRESHOLD_IN_TRACK_M_S = std::numeric_limits<double>::quiet_NaN(),
    double THRESHOLD_PLANE_M_S = std::numeric_limits<double>::quiet_NaN(),
    bool CROSSING_AT_EDGE = false,
    int64_t SPAN_START_MS = 0,
    int64_t SPAN_STOP_MS = 0,
    double GLR_STATISTIC = std::numeric_limits<double>::quiet_NaN(),
    double STEP_M_S = std::numeric_limits<double>::quiet_NaN(),
    double STEP_SD_M_S = std::numeric_limits<double>::quiet_NaN(),
    double SIGMA_M_S = std::numeric_limits<double>::quiet_NaN(),
    double TREND_M_S_PER_DAY = std::numeric_limits<double>::quiet_NaN(),
    int64_t OLD_LEVEL_SET_MS = 0,
    int64_t NEW_LEVEL_SET_MS = 0,
    mdeTimeBasis TIME_BASIS = mdeTimeBasis_Unspecified,
    double PLANE_GLR_STATISTIC = std::numeric_limits<double>::quiet_NaN(),
    double PLANE_STEP_M_S = std::numeric_limits<double>::quiet_NaN(),
    double RATE_CHANGE_M_S_PER_DAY = std::numeric_limits<double>::quiet_NaN(),
    double RATE_CHANGE_SD = std::numeric_limits<double>::quiet_NaN(),
    double TREND_BEFORE_M_S_PER_DAY = std::numeric_limits<double>::quiet_NaN(),
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<MDEEvidence>>> COMPONENTS = 0,
    mdeDetector KEPT = mdeDetector_Unspecified) {
  MDEEvidenceBuilder builder_(_fbb);
  builder_.add_TREND_BEFORE_M_S_PER_DAY(TREND_BEFORE_M_S_PER_DAY);
  builder_.add_RATE_CHANGE_SD(RATE_CHANGE_SD);
  builder_.add_RATE_CHANGE_M_S_PER_DAY(RATE_CHANGE_M_S_PER_DAY);
  builder_.add_PLANE_STEP_M_S(PLANE_STEP_M_S);
  builder_.add_PLANE_GLR_STATISTIC(PLANE_GLR_STATISTIC);
  builder_.add_NEW_LEVEL_SET_MS(NEW_LEVEL_SET_MS);
  builder_.add_OLD_LEVEL_SET_MS(OLD_LEVEL_SET_MS);
  builder_.add_TREND_M_S_PER_DAY(TREND_M_S_PER_DAY);
  builder_.add_SIGMA_M_S(SIGMA_M_S);
  builder_.add_STEP_SD_M_S(STEP_SD_M_S);
  builder_.add_STEP_M_S(STEP_M_S);
  builder_.add_GLR_STATISTIC(GLR_STATISTIC);
  builder_.add_SPAN_STOP_MS(SPAN_STOP_MS);
  builder_.add_SPAN_START_MS(SPAN_START_MS);
  builder_.add_THRESHOLD_PLANE_M_S(THRESHOLD_PLANE_M_S);
  builder_.add_THRESHOLD_IN_TRACK_M_S(THRESHOLD_IN_TRACK_M_S);
  builder_.add_STEP_PLANE_M_S(STEP_PLANE_M_S);
  builder_.add_STEP_IN_TRACK_M_S(STEP_IN_TRACK_M_S);
  builder_.add_TIME_MS(TIME_MS);
  builder_.add_COMPONENTS(COMPONENTS);
  builder_.add_PAIR_INDEX(PAIR_INDEX);
  builder_.add_KEPT(KEPT);
  builder_.add_TIME_BASIS(TIME_BASIS);
  builder_.add_CROSSING_AT_EDGE(CROSSING_AT_EDGE);
  builder_.add_DETECTOR(DETECTOR);
  return builder_.Finish();
}

