  const ::flatbuffers::String *DETAIL() const {
    return GetPointer<const ::flatbuffers::String *>(VT_DETAIL);
  }
  /// Pre-burn and post-burn version descriptions; empty = none.
  const ::flatbuffers::String *PRE() const {
    return GetPointer<const ::flatbuffers::String *>(VT_PRE);
  }
  const ::flatbuffers::String *POST() const {
    return GetPointer<const ::flatbuffers::String *>(VT_POST);
  }
  /// Window compared, Unix ms.
