  uint32_t EXPLAINED() const {
    return GetField<uint32_t>(VT_EXPLAINED, 0);
  }
  uint32_t FALSE_ALARMS() const {
    return GetField<uint32_t>(VT_FALSE_ALARMS, 0);
  }
  /// Object-years assessed.
  double OBJECT_YEARS() const {
    return GetField<double>(VT_OBJECT_YEARS, 0.0);
  }
  double FALSE_ALARMS_PER_OBJECT_YEAR() const {
    return GetField<double>(VT_FALSE_ALARMS_PER_OBJECT_YEAR, std::numeric_limits<double>::quiet_NaN());
  }
