           VerifyField<uint32_t>(verifier, VT_DETECTED, 4) &&
           VerifyField<double>(verifier, VT_RECALL, 8) &&
           VerifyField<double>(verifier, VT_WILSON95_LOW, 8) &&
           VerifyField<double>(verifier, VT_WILSON95_HIGH, 8) &&
           VerifyOffset(verifier, VT_BY_DELTA_V) &&
           verifier.VerifyVector(BY_DELTA_V()) &&
           verifier.VerifyVectorOfTables(BY_DELTA_V()) &&
           VerifyOffset(verifier, VT_TIME_ERROR_ABS_S) &&
           verifier.VerifyTable(TIME_ERROR_ABS_S()) &&
           VerifyOffset(verifier, VT_DV_RATIO) &&
           verifier.VerifyTable(DV_RATIO()) &&
           VerifyOffset(verifier, VT_IN_TRACK_RATIO) &&
           verifier.VerifyTable(IN_TRACK_RATIO()) &&
           VerifyField<uint32_t>(verifier, VT_UNMATCHED_EVENTS, 4) &&
           VerifyField<uint32_t>(verifier, VT_EXPLAINED, 4) &&
           VerifyField<uint32_t>(verifier, VT_FALSE_ALARMS, 4) &&
           VerifyField<double>(verifier, VT_OBJECT_YEARS, 8) &&
           VerifyField<double>(verifier, VT_FALSE_ALARMS_PER_OBJECT_YEAR, 8) &&
           verifier.EndTable();
